// EDIT THESE VALUES ONCE, then activate the workflow
return [{ json: {
  "sheetId": "PASTE_SHEET_ID",
  "business": "Your Business",
  "fromName": "Your Name",
  "payLink": "",
  "levels": [
    3,
    10,
    20
  ]
} }];

const C = $('Config').first().json;
const today = new Date(); today.setHours(0,0,0,0);
const iso = d => d.toISOString().slice(0,10);
const parse = v => { if (!v && v !== 0) return null; if (typeof v === 'number') { const d = new Date(Date.UTC(1899,11,30) + v*864e5); return isNaN(d) ? null : d; } const d = new Date(v); return isNaN(d) ? null : d; };
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const days = (a, b) => Math.floor((b - a) / 864e5);
const fill = (t, o) => t.replace(/\{(\w+)\}/g, (_, k) => (o[k] ?? ''));

const T = [
  ['Friendly reminder: invoice {inv} ({amt})', 'Hi {first},\n\nA quick reminder that invoice {inv} for {amt} was due on {due}. If it is already on its way, thank you and please ignore this note.{pay}\n\nBest,\n{from}'],
  ['Invoice {inv} is now {d} days overdue', 'Hi {first},\n\nInvoice {inv} for {amt} is now {d} days past due (due {due}). Could you let me know when we can expect payment?{pay}\n\nThank you,\n{from}'],
  ['Final notice: invoice {inv} ({amt})', 'Hi {first},\n\nThis is a final notice for invoice {inv} ({amt}), {d} days overdue. Please arrange payment this week or reply to discuss a plan.{pay}\n\nRegards,\n{from}'],
];
const out = [];
for (const it of $input.all()) {
  const r = it.json; if (/^(yes|y|true|paid)$/i.test(String(r['Paid']||'')) || !r['Email']) continue;
  const due = parse(r['Due date']); if (!due) continue;
  const d = days(due, today); const sent = num(r['Reminder level']);
  let lvl = 0; C.levels.forEach((x, i) => { if (d >= x) lvl = i + 1; });
  if (lvl === 0 || lvl <= sent) continue;
  const o = { inv: r['Invoice #'], amt: '$' + num(r['Amount']).toLocaleString('en-US', {minimumFractionDigits: 2}), due: iso(due), d,
    first: String(r['Client']||'').split(' ')[0] || 'there', from: C.fromName, pay: C.payLink ? `\n\nPay online: ${C.payLink}` : '' };
  out.push({ json: { row_number: r.row_number, level: lvl, email: r['Email'], subject: fill(T[lvl-1][0], o), body: fill(T[lvl-1][1], o) } });
}
return out;
